    'RegisterSimpleRisk'=>'Региструјте SimpleRisk',
    'RegistrationText'=>'Регистрованим инстанцама система SimpleRisk одмах се додељује приступ екстензијама Upgrade и Secure Controls Framework (SCF). Екстензија Upgrade пружа могућност прављења резервне копије и ажурирања ваше инстанце система SimpleRisk једним кликом. Екстензија Secure Controls Framework (SCF) пружа заједнички оквир контрола који је интегрисан у функционалност управљања (Governance) у систему SimpleRisk. Приликом регистрације система SimpleRisk, ваше информације о регистрацији биће послате на сервер који хостује SimpleRisk. SimpleRisk ће користити достављене информације о регистрацији да обавести кориснике о новим издањима и безбедносним ажурирањима. Регистрацијом система SimpleRisk пријављујете се на наше маркетиншке комуникације, али се можете одјавити у било ком тренутку помоћу везе за одјаву у тим порукама. SimpleRisk поштује приватност наших купаца и информације достављене нама током процеса регистрације система SimpleRisk никада неће бити продате трећој страни.',
