    'AdminRoleDescription' => 'Ова дозвола обезбеђује приступ конфигурацијама СимплеРиск-а. Корисник са овом дозволом је ефективно административни корисник на систему. Они могу да направе промене у свим менијима који се налазе у менију "Конфигурисање". То ће такође омогућити активирање и деактивирање додатака и измену њихових конфигурација. Ову дозволу треба дати само онима који имају апсолутну потребу за тим. Када корисник буде имао приступ овој дозволи моћи ће да уређује и друге корисничке налоге.',
