    // Configure Hub - tile descriptions (system category)
    'SettingsDesc'                        => 'Конфигуришите подешавања за цео систем: основни URL, безбедност, подразумевани језик, временску зону, подразумеване вредности за бодовање ризика и још много тога.',
    'SettingsPreferencesDesc'             => 'Подразумеване вредности и преференције понашања у SimpleRisk-у: језик, временска зона, статуси ревизије, захтеви за мапирање ризика, прекидачи понашања корисничког интерфејса и слично.',
    'SettingsFileUploadDesc'              => 'Дозвољени типови датотека за отпремање и ограничења величине за различита поља за прилагање датотека.',
    'SettingsMailDesc'                    => 'SMTP конфигурација за одлазна обавештења путем е-поште, укључујући транспорт, хост, аутентификацију и адресу за одговор.',
    'SettingsBackupsDesc'                 => 'Конфигуришите чување резервних копија, заказивање и линкове за преузимање за резервне копије базе података SimpleRisk.',
    'SettingsSecurityDesc'                => 'Подешавања безбедности за аутентификацију, сесију, политику лозинки, основни URL и API.',
    'SettingsLoggingDesc'                 => 'Конфигурација дневника за отклањање грешака и ревизију: нивои дневника, задржавање и локација датотека дневника.',
    'HealthCheckDesc'                     => 'Дијагностикујте статус система: PHP верзију, екстензије, дозволе за датотеке, повезаност са базом података, cron распоред и активације Extra модула.',
    'AnnouncementsDesc'                   => 'Саставите и управљајте банер обавештењима видљивим свим корисницима.',
    'RegisterAndUpgradeDesc'              => 'Региструјте своју инсталацију система SimpleRisk, унесите или обновите претплатнички кључ и покрените надоградње Core/Extra модула једним кликом.',
    'QueueMonitorDesc'                    => 'Прегледајте ред позадинских задатака: задатке на чекању, у току и неуспеле задатке.',
    'ExtrasDesc'                          => 'Активирајте, деактивирајте и конфигуришите SimpleRisk Extra модуле (плаћене додатке).',
    'ArtificialIntelligenceExtraDesc'     => 'Extra модул Artificial Intelligence пружа унапређену анализу ризика (укључујући FAIR процене) и прилагођену документацију.',
    'CustomizationExtraDesc'              => 'Додатна функција за прилагођавање омогућава додавање и уклањање различитих типова поља и динамичко креирање прилагођених шаблона страница.',
    'NotificationExtraDesc'               => 'Extra модул Email Notification омогућава систему SimpleRisk да шаље обавештења путем е-поште када се ризици поднесу, измене или се над њима предузме друга акција. Овај Extra модул се такође може додати као заказана скрипта за слање редовних подсетника када су ризици спремни за преглед од стране руководства. У производу SimpleRisk Core, без овог Extra модула, обавештења се не саопштавају изван самог алата.',
    'VulnerabilityManagementExtraDesc'    => 'Додатна опција за управљање рањивостима пружа корисницима могућност интеграције своје инстанце SimpleRisk-а са Qualys, Tenable.io или Rapid7 Nexpose/InsightVM и увоза података о средствима и рањивостима у SimpleRisk. Одатле можете одабрати које локације желите да покријете, одредити које оцене рањивости треба увести и проценити које рањивости се претварају у ризике како бисте их пратили.',
    'IncidentManagementExtraDesc'         => 'Додатак за управљање инцидентима заснован је на NIST 800-61 Водичу за руковање инцидентима у области безбедности рачунара и пружа могућности управљања инцидентима из самог система SimpleRisk.',

    // Configure Hub - tile descriptions (customization category)
    'RedefineNamingConventionsDesc'       => 'Преименујте терминологију система SimpleRisk (ризик, имовина, оквир итд.) у целом корисничком интерфејсу.',
    'RiskConfigurationDesc'               => 'Конфигуришите правила оцењивања ризика: нивое, апетит за ризик, SLA прагове и класичне формуле ризика / формуле ризика засноване на доприносним факторима.',
    'RiskAndThreatCatalogDesc'            => 'Одржавајте каталог вредности ризика и претњи које се користе у падајућим менијима.',
    'AddAndRemoveValuesDesc'              => 'Управљајте вредностима падајућег менија за поља ризика: локација, извор, категорија, тим, технологија и још много тога.',
    'AssetValuationDesc'                  => 'Конфигуришите скалу вредновања имовине и појединачна прилагођавања вредновања по имовини.',

    // Configure Hub - tile descriptions (users category)
    'UserManagementDesc'                  => 'Додајте, уредите, онемогућите и ресетујте кориснике; управљајте политиком лозинки.',
    'RoleManagementDesc'                  => 'Дефинишите улоге и дозволе које свака улога додељује.',
    'TeamManagementDesc'                  => 'Креирајте тимове и управљајте њима; користе се за филтрирање видљивости записа.',
    'SeparationExtraDesc'                 => 'Додатак за раздвајање на основу тима ограничава преглед ризика само на кориснике који су чланови тима коме је ризик додељен. У производу SimpleRisk Core, без овог додатка, сваки корисник може да види сваки ризик.',
    'CustomAuthenticationExtraDesc'       => 'Додатак за прилагођену аутентификацију пружа подршку за Active Directory и SAML аутентификацију. У производу SimpleRisk Core, без овог додатка, једина опција је креирање нових корисника у SimpleRisk репозиторијуму идентитета.',
    'EncryptionExtraDesc'                 => 'Extra модул Encrypted Database генерише насумичан AES-256 битни кључ за шифровање и затим га користи за шифровање осетљивог текста пре уметања у базу података система SimpleRisk. Тиме се спречава да било ко може да прегледа или мења податке без директног коришћења апликације SimpleRisk.',
    'OrganizationManagementDesc'          => "Додатак Организациона хијерархија омогућава дефинисање више пословних јединица које могу да укључују било који број тимова. Корисници затим могу бити распоређени у један или више тимова у оквиру различитих пословних јединица. Ово утиче на могућност корисника да види и користи тимове, кориснике и средства са којима није повезан.",

    // Configure Hub - tile descriptions (data category)
    'DeleteRisksDesc'                     => 'Групно обришите ризике. Користите штедљиво — брисања су трајна.',
    'AuditTrailDesc'                      => 'Претражите и извезите дневник системске ревизије корисничких акција.',
    'ImportExportExtraDesc'               => 'Додатак за увоз-извоз пружа могућност увоза података у SimpleRisk мапирањем поља у CSV датотеци са пољима у бази података SimpleRisk. Може се користити за увоз резултата ревизије из табеле треће стране, резултата скенирања рањивости из другог алата, средстава из ваше CMDB базе података и још много тога. Додатак такође пружа могућност извоза CSV датотека из SimpleRisk-а које садрже ризике, ублажавања, прегледе или комбиновани извештај за сва три.',
    'JiraExtraDesc'                       => 'Jira Integration Extra пружа корисницима могућност двосмерне интеграције са Jira инстанцом. Омогућава повезивање ризика са Jira проблемима, као и синхронизацију њихових података, статуса и коментара.',
    'APIExtraDesc'                        => 'API Extra омогућава корисницима да користе RESTful API за креирање скриптованих интеракција са другим апликацијама како би постигли напредну аутоматизацију и искористили постојећу инфраструктуру.',
    'AdvancedSearchExtraDesc'             => 'Extra модул Advanced Search претвара поље за претрагу у горњој траци у јединствену претрагу кроз ризике, оквире, контроле, документе, изузетке, тестове, ревизије, имовину и групе имовине, уз потпуну страницу претраге за преглед резултата. Приказује само записе које корисник има дозволу да види.',
    'AssessmentsExtraDesc'                => 'Extra модул Risk Assessment омогућава корисницима да дефинишу контакте, креирају питања (укључујући логику), саставе више питања помоћу шаблона упитника, креирају упитнике и шаљу их контактима, прегледају резултате упитника, додају ризике на основу тих резултата, упоређују резултате током времена, увозе и извозе екстерно прилагођене процене и прегледају дневник ревизије процене ризика.',
    'ActiveAssessmentsDesc'               => 'Прегледајте процене које су тренутно у току и управљајте њима.',
    'WorkflowsExtraDesc'                  => 'Extra модул Workflows пружа визуелни, догађајима вођен механизам токова рада који аутоматизује акције управљања ризицима као одговор на догађаје унутар система SimpleRisk. Можете дизајнирати токове рада који се покрећу при променама — као што је подношење, ажурирање или преглед ризика — ради усмеравања одобрења, додељивања послова и одржавања процеса у току без ручне интервенције.',

    // Configure Hub - tile descriptions (frameworks category)
    'SCFExtraDesc'                        => "Оквир безбедних контрола (SCF) Екстра је директна интеграција између Оквира безбедних контрола и SimpleRisk-а. Он увози SCF-ов каталог контрола и њихова мапирања у широком спектру оквира за усклађеност и сајбер безбедност у SimpleRisk-ову функционалност управљања, тако да можете усвојити оквире који су вам потребни и управљати њиховим контролама без ручног креирања.",

    // Configure Hub - tile descriptions (maintenance category)
