    'EncryptionPipelineStalledTask' => 'Изгледа да је процес шифровања (задатак #{$id}, {$type}) заглавио — већ неуобичајено дуго има статус {$status} без напретка. То обично значи да радник реда у позадини није покренут; проверите да ли је заказан, а затим покушајте поново када обради заглављени задатак.',
    'EncryptionPipelineStalledState' => 'Изгледа да је процес шифровања заглавио — неуобичајено дуго је означен као у току, а не постоји одговарајући задатак у позадини на који би се могло указати. То обично значи да радник реда није покренут или да је претходни процес завршен без исправног ажурирања овога. Проверите дневник за отклањање грешака пре него што покушате поново.',
