    'AssetScoringScoreHelp' => 'Пондерисани скор спаја три оцене у један број од {$low} до {$high}. Свака оцена постаје своја задата вредност, а свака се множи тежином свог циља. Резултати се сабирају и деле укупно збиром тежина. Поверљивост са вредношћу Није применљиво изоставља се, заједно са својом тежином. Задате вредности и тежине подешавају се у Подешавањима. Сва три циља морају бити оцењена пре него што се скор прикаже.',
    'AssetScoringCategorizationHelp' => 'FIPS 199 категоризација безбедности је највиша вредност (high-water mark): највећа оцена међу циљевима који су применљиви. Једна оцена Висок чини имовину Високом, без обзира на остале. Није применљиво се занемарује.',
