    // SR-115: HTTP Strict Transport Security (HSTS)
    'EnableHSTS' => 'Омогући HTTP Strict Transport Security (HSTS)',
    'EnableHSTSHelp' => 'Налаже прегледачима да се на SimpleRisk повезују искључиво преко HTTPS-а током доле наведеног максималног трајања. Омогућите ово тек пошто HTTPS поуздано ради на овом сајту: прегледачи који су видели заглавље одбијаће обичан HTTP, а неисправан сертификат се не може заобићи док максимално трајање не истекне. Почните са кратким максималним трајањем, на пример 300 секунди, и повећајте га када се HTTPS потврди.',
    'HSTSMaxAge' => 'HSTS максимално трајање (секунде)',
